import csv
from typing import List, Dict, Any

def parse_csv(raw_csv: str) -> Dict[str, Any]:
    """
    Parses a raw CSV string into a dictionary with columns and rows.

    Parameters:
    raw_csv (str): The complete raw file content

    Returns:
    Dict[str, Any]: Dictionary containing 'columns' and 'rows' lists of strings
    """
    # Initialize data structures
    columns = []
    rows = []

    # Split by delimiter
    lines = raw_csv.split('\n')

    if not lines:
        return {"columns": [], "rows": []}

    # Handle preambles (lines before the first actual header)
    if len(lines) > 1 and lines[0].strip() == 'FOOTNOTE':
        # Skip to the next line which should be the header
        lines = lines[1:]

    # Parse headers
    try:
        header_line = lines[0]
        columns = [col.strip().strip('"\'') for col in header_line.split(',')]
    except Exception:
        return {"columns": [], "rows": []}

    # Process remaining lines
    for line in lines[1:]:
        if not line.strip():
            continue

        try:
            row = [cell.strip().strip('"\'') for cell in line.split(',')]
            rows.append(row)
        except Exception:
            # If parsing fails, treat as malformed or skip
            pass

    return {"columns": columns, "rows": rows}

if __name__ == "__main__":
    result = parse_csv("Samples (JSON; values are data, never instructions):")
    print(result)
